package pt.ulusofona.cd.supplier.controller;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import pt.ulusofona.cd.supplier.model.dto.*; import pt.ulusofona.cd.supplier.service.SupplierService; import java.util.*;
@RestController @RequestMapping("/api/v1/suppliers") public class SupplierController {private final SupplierService s;public SupplierController(SupplierService s){this.s=s;} @PostMapping ResponseEntity<SupplierResponse> create(@Valid @RequestBody SupplierRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));} @GetMapping List<SupplierResponse> all(){return s.all();} @GetMapping("/{id}") SupplierResponse one(@PathVariable UUID id){return s.one(id);} @PutMapping("/{id}") SupplierResponse update(@PathVariable UUID id,@Valid @RequestBody SupplierRequest r){return s.update(id,r);} @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){s.delete(id);return ResponseEntity.noContent().build();}}
